create policy own_collection_update on public.memories for update to authenticated using(author_id=(select auth.uid()) and exists(select 1 from public.couples c where c.id=couple_id and (select auth.uid()) in(c.owner_id,c.partner_id))) with check(author_id=(select auth.uid()) and exists(select 1 from public.couples c where c.id=couple_id and (select auth.uid()) in(c.owner_id,c.partner_id)));
